// Seats: the behaviour every seat prefab shares, ported from Creator Hub's
// smart-item Seat.ts (packs/smart_items/assets/*/Seat.ts, creator-hub#1354).
//
//   import { SeatBehavior } from '~runtime/seat'
//   export class Seat extends SeatBehavior {
//     constructor(public src: string, public entity: Entity,
//       public hoverText: string = 'Sit Here', public takenMessage: string = 'Seat is taken') {
//       super(src, entity, hoverText, takenMessage, { sceneEmotes: [] })
//     }
//     /** @action */ sit(): void { super.sit() }
//     /** @action */ markAsFree(): void { super.markAsFree() }
//   }
//
// Sit spots are the child entities named "Sit Spot…", carrying only a Transform;
// with none (the standalone Sit Spot), the entity itself is the spot. Clicking a
// spot sits the player there (or on the nearest free one if it is taken): the
// avatar is moved onto it facing forward, then a looping sitting emote plays.
// Moving cancels the emote engine-side, as in Creator Hub and Genesis Plaza.
//
// Each spot's Free/Taken state is an `asset-packs::States` value synced under
// SEAT_SYNC_BASE + the spot's entity number, so every player sees the same
// availability. The client of the player who sat down frees it: once the avatar
// arrived (or failed to within ARRIVE_TIMEOUT_S), walking STAND_UP_DISTANCE away
// stands them up. A sitter who disconnects, reloads or teleports out never gets
// there, so any client that sees a taken spot with nobody on it for VACANT_FOR_S
// frees it.
//
// `sit()` sits the player on the nearest free spot, or shows `takenMessage` on
// screen when every spot is taken; `markAsFree()` frees them all. Both are
// `@action` methods on the prefab's class, so other smart items and the Admin
// Tools panel can call them (call_script_method).
//
// Editor-side differences from Creator Hub's script, kept on purpose: each spot
// gets its own pointer collider (a model's own colliders do not reliably cover
// the spot), the click is the pointer button so it works on touch, a glowing dot
// hints free spots to nearby players, a seat can ship its own emote clips, and
// nothing but the occupancy sync runs on the Multiplayer Server.
import {
  ColliderLayer,
  Font,
  InputAction,
  Material,
  MeshCollider,
  MeshRenderer,
  PointerEvents,
  PlayerIdentityData,
  PointerFilterMode,
  Schemas,
  TextAlignMode,
  Transform,
  UiText,
  UiTransform,
  VisibilityComponent,
  YGUnit,
  engine,
  pointerEventsSystem,
  type Entity,
  type LastWriteWinElementSetComponentDefinition
} from '@dcl/sdk/ecs'
import { Quaternion, Vector3 } from '@dcl/sdk/math'
import { isServer, syncEntity } from '@dcl/sdk/network'
import { movePlayerTo, triggerEmote, triggerSceneEmote } from '~system/RestrictedActions'

const SPOT_NAME_PREFIX = 'sit spot'
const MAX_DISTANCE = 6
const EMOTE_DELAY_S = 0.25
const STAND_UP_DISTANCE = 1.5
const ARRIVE_TIMEOUT_S = 3
const MESSAGE_S = 2
// longer than ARRIVE_TIMEOUT_S, so a sitter still on the way is never evicted
const VACANT_FOR_S = 6
const REAP_EVERY_S = 2
// syncEntity's id is scene-wide, shared with every other syncEntity call: the
// seats take a range of their own ("SEA7") instead of raw entity numbers, which
// a scene handing out its own ids from 512 up could reuse
const SEAT_SYNC_BASE = 0x5ea70000
const SITTING_EMOTES = ['sittingChair1', 'sittingChair2']
const FREE = 'Free'
const TAKEN = 'Taken'

// the Plaza-style "you can sit here" hint: a small glowing dot floating over
// each free spot, pulsing gently, shown only to nearby players
const DOT_VISIBLE_DIST = 10
const DOT_OCCUPIED_DIST = 0.9
const DOT_HEIGHT = 0.55
const DOT_SIZE = 0.09
const DOT_PULSE = 0.25

export interface SeatOptions {
  // emote .glb files in the prefab's folder, played with triggerSceneEmote;
  // empty plays the predefined chair emotes
  sceneEmotes?: string[]
}

type NameComponent = LastWriteWinElementSetComponentDefinition<{ value: string }>
interface StatesValue {
  id: number
  value: string[]
  defaultValue?: string
  currentValue?: string
  previousValue?: string
}
type StatesComponent = LastWriteWinElementSetComponentDefinition<StatesValue>

// Defined at module load: the engine refuses new components once the scene is
// running, and start() is too late. defineComponent hands back the existing
// definition when the scene's asset-packs runtime (or a sibling seat) already
// registered the name. The States spec is the asset-packs registry's, field for field.
const Name: NameComponent = engine.defineComponent('core-schema::Name', { value: Schemas.String })
const States: StatesComponent = engine.defineComponent('asset-packs::States', {
  id: Schemas.Number,
  value: Schemas.Array(Schemas.String),
  defaultValue: Schemas.Optional(Schemas.String),
  currentValue: Schemas.Optional(Schemas.String),
  previousValue: Schemas.Optional(Schemas.String)
})

function isSpotName(name: unknown): boolean {
  return typeof name === 'string' && name.toLowerCase().startsWith(SPOT_NAME_PREFIX)
}

function sceneRelativeTransform(entity: Entity): { position: Vector3; rotation: Quaternion } {
  const chain: Entity[] = []
  let cursor = entity
  while (cursor !== engine.RootEntity && chain.length < 32) {
    chain.push(cursor)
    const t = Transform.getOrNull(cursor)
    if (t === null) break
    cursor = t.parent ?? engine.RootEntity
  }
  let position = Vector3.Zero()
  let rotation = Quaternion.Identity()
  let scale = Vector3.One()
  for (const link of chain.reverse()) {
    const t = Transform.getOrNull(link)
    if (t === null) continue
    const local = Vector3.create(t.position.x * scale.x, t.position.y * scale.y, t.position.z * scale.z)
    position = Vector3.add(position, Vector3.rotate(local, rotation))
    rotation = Quaternion.multiply(rotation, t.rotation)
    scale = Vector3.create(scale.x * t.scale.x, scale.y * t.scale.y, scale.z * t.scale.z)
  }
  return { position, rotation }
}

export class SeatBehavior {
  private spots: Entity[] = []
  private dots: Array<{ spot: Entity; dot: Entity; visible: boolean }> = []
  private sittingOn: Entity | null = null
  private seated = false
  private arriveTimer = 0
  private emoteIn = 0
  private time = 0
  private hover = new Map<Entity, string>()
  private message: Entity | null = null
  private messageTimer = 0
  private client = false
  private reapIn = REAP_EVERY_S
  private vacantFor = new Map<Entity, number>()

  constructor(
    public src: string,
    public entity: Entity,
    public hoverText: string,
    public takenMessage: string,
    private readonly options: SeatOptions = {}
  ) {}

  start(): void {
    for (const [child, transform] of engine.getEntitiesWith(Transform)) {
      if (transform.parent !== this.entity) continue
      if (isSpotName(Name.getOrNull(child)?.value)) this.spots.push(child)
    }
    if (this.spots.length === 0) this.spots.push(this.entity)

    for (const spot of this.spots) {
      if (States.getOrNull(spot) === null) {
        States.create(spot, { id: spot, value: [FREE, TAKEN], defaultValue: FREE, currentValue: FREE })
      }
      // a composite entity's number is the same on every peer
      try {
        syncEntity(spot, [States.componentId], SEAT_SYNC_BASE + (spot as number))
      } catch (error) {
        console.log(`seat: could not share whether sit spot ${spot} is taken`, error)
      }
    }
    // The hint walks a transform chain per spot per frame, and a seat is placed
    // by the dozen: the Multiplayer Server only keeps the occupancy in sync.
    if (isServer()) return
    this.client = true

    for (const spot of this.spots) {
      MeshCollider.setBox(spot, ColliderLayer.CL_POINTER)
      this.hover.set(spot, this.hoverText)
      pointerEventsSystem.onPointerDown(
        { entity: spot, opts: { button: InputAction.IA_POINTER, hoverText: this.hoverText, maxDistance: MAX_DISTANCE } },
        () => this.sitOn(this.isAvailable(spot) ? spot : this.nearestFreeSpot())
      )
      // no collider on the dot: clicks pass through to the spot beneath it
      const dot = engine.addEntity()
      Transform.create(dot, {
        parent: spot,
        position: Vector3.create(0, DOT_HEIGHT, 0),
        scale: Vector3.create(DOT_SIZE, DOT_SIZE, DOT_SIZE)
      })
      MeshRenderer.setSphere(dot)
      Material.setPbrMaterial(dot, {
        albedoColor: { r: 1, g: 1, b: 1, a: 0.85 },
        emissiveColor: { r: 1, g: 1, b: 1 },
        emissiveIntensity: 2,
        roughness: 1
      })
      VisibilityComponent.create(dot, { visible: false })
      this.dots.push({ spot, dot, visible: false })
    }
  }

  update(dt: number): void {
    if (!this.client) return
    this.time += dt
    if (this.messageTimer > 0) {
      this.messageTimer -= dt
      if (this.messageTimer <= 0) this.hideMessage()
    }
    this.trackSitter(dt)
    this.reapAbandoned(dt)
    this.refreshHover()
    this.updateDots()
    this.playEmoteWhenSettled(dt)
  }

  /** Sits the player on the nearest free sit spot, or shows the taken message if every spot is taken. */
  sit(): void {
    if (!this.client) return
    this.sitOn(this.nearestFreeSpot())
  }

  /** Marks every sit spot of this seat as free. */
  markAsFree(): void {
    for (const spot of this.spots) this.setSpotState(spot, FREE)
    this.sittingOn = null
    this.seated = false
  }

  private sitOn(spot: Entity | null): void {
    if (spot === null) {
      this.showMessage()
      return
    }
    if (this.sittingOn !== null && this.sittingOn !== spot) this.setSpotState(this.sittingOn, FREE)
    const world = sceneRelativeTransform(spot)
    const forward = Vector3.rotate(Vector3.Forward(), world.rotation)
    void movePlayerTo({ newRelativePosition: world.position, avatarTarget: Vector3.add(world.position, forward) })
    this.setSpotState(spot, TAKEN)
    this.sittingOn = spot
    this.seated = false
    this.arriveTimer = ARRIVE_TIMEOUT_S
    // let the move land before the emote starts, or the walk cancels it
    this.emoteIn = EMOTE_DELAY_S
  }

  private playEmoteWhenSettled(dt: number): void {
    if (this.emoteIn <= 0) return
    this.emoteIn -= dt
    if (this.emoteIn > 0) return
    const sceneEmotes = this.options.sceneEmotes ?? []
    if (sceneEmotes.length > 0) {
      // src is the script's directory (custom/<slug>/scripts) — the emotes live
      // one level up, in the placed prefab's own folder
      const root = this.src.replace(/\/scripts\/?$/, '')
      const emote = sceneEmotes[Math.floor(Math.random() * sceneEmotes.length)]
      void triggerSceneEmote({ src: `${root}/${emote}`, loop: true })
      return
    }
    void triggerEmote({ predefinedEmote: SITTING_EMOTES[Math.floor(Math.random() * SITTING_EMOTES.length)] })
  }

  // movePlayerTo takes a few frames to land, so until the avatar has arrived the
  // player is still where they clicked from, and a stand-up check would free the
  // spot right away. If the avatar never arrives, the move was rejected.
  private trackSitter(dt: number): void {
    if (this.sittingOn === null) return
    const player = Transform.getOrNull(engine.PlayerEntity)
    if (player === null) return
    const distance = Vector3.distance(player.position, sceneRelativeTransform(this.sittingOn).position)
    if (!this.seated) {
      if (distance <= STAND_UP_DISTANCE) {
        this.seated = true
        return
      }
      this.arriveTimer -= dt
      if (this.arriveTimer <= 0) this.standUp()
      return
    }
    if (distance > STAND_UP_DISTANCE) this.standUp()
  }

  // States is last-write-wins, so it does not matter which client frees it
  private reapAbandoned(dt: number): void {
    this.reapIn -= dt
    if (this.reapIn > 0) return
    const elapsed = REAP_EVERY_S - this.reapIn
    this.reapIn = REAP_EVERY_S
    const avatars: Vector3[] = []
    for (const [, transform] of engine.getEntitiesWith(Transform, PlayerIdentityData)) avatars.push(transform.position)
    const me = Transform.getOrNull(engine.PlayerEntity)
    if (me !== null) avatars.push(me.position)
    for (const spot of this.spots) {
      if (spot === this.sittingOn || States.getOrNull(spot)?.currentValue !== TAKEN) {
        this.vacantFor.delete(spot)
        continue
      }
      const at = sceneRelativeTransform(spot).position
      if (avatars.some((position) => Vector3.distance(position, at) <= STAND_UP_DISTANCE)) {
        this.vacantFor.delete(spot)
        continue
      }
      const vacant = (this.vacantFor.get(spot) ?? 0) + elapsed
      if (vacant < VACANT_FOR_S) {
        this.vacantFor.set(spot, vacant)
        continue
      }
      this.vacantFor.delete(spot)
      this.setSpotState(spot, FREE)
    }
  }

  private standUp(): void {
    if (this.sittingOn !== null) this.setSpotState(this.sittingOn, FREE)
    this.sittingOn = null
    this.seated = false
  }

  // The spot the local player sits on counts as available to them, so clicking
  // it again re-seats them instead of reporting it as taken.
  private isAvailable(spot: Entity): boolean {
    if (spot === this.sittingOn) return true
    return States.getOrNull(spot)?.currentValue !== TAKEN
  }

  private nearestFreeSpot(): Entity | null {
    const player = Transform.getOrNull(engine.PlayerEntity)?.position
    let nearest: Entity | null = null
    let nearestDistance = Infinity
    for (const spot of this.spots) {
      if (!this.isAvailable(spot)) continue
      const distance = player === undefined ? 0 : Vector3.distance(player, sceneRelativeTransform(spot).position)
      if (distance < nearestDistance) {
        nearestDistance = distance
        nearest = spot
      }
    }
    return nearest
  }

  private setSpotState(spot: Entity, next: string): void {
    const current = States.getOrNull(spot)
    if (current === null || current.currentValue === next) return
    const states = States.getMutable(spot)
    states.previousValue = states.currentValue
    states.currentValue = next
  }

  // a taken spot says so in its hover hint, unless the seat has no taken message
  private refreshHover(): void {
    for (const spot of this.spots) {
      const text = this.isAvailable(spot) || this.takenMessage === '' ? this.hoverText : this.takenMessage
      if (this.hover.get(spot) === text) continue
      this.hover.set(spot, text)
      const events = PointerEvents.getMutableOrNull(spot)
      if (events === null) continue
      for (const event of events.pointerEvents) {
        if (event.eventInfo !== undefined) event.eventInfo.hoverText = text
      }
    }
  }

  private updateDots(): void {
    const player = Transform.getOrNull(engine.PlayerEntity)?.position
    const pulse = 1 + DOT_PULSE * Math.sin(this.time * 3)
    for (const entry of this.dots) {
      let visible = false
      if (player !== undefined && this.isAvailable(entry.spot)) {
        const dist = Vector3.distance(player, sceneRelativeTransform(entry.spot).position)
        // hidden while you are on the spot: a glow over a seated avatar's head
        // reads as a bug, not a hint
        visible = dist < DOT_VISIBLE_DIST && dist > DOT_OCCUPIED_DIST
      }
      if (entry.visible !== visible) {
        entry.visible = visible
        VisibilityComponent.getMutable(entry.dot).visible = visible
      }
      if (visible) Transform.getMutable(entry.dot).scale = Vector3.create(DOT_SIZE * pulse, DOT_SIZE * pulse, DOT_SIZE * pulse)
    }
  }

  private showMessage(): void {
    if (this.takenMessage === '') return
    this.hideMessage()
    const text = engine.addEntity()
    const ui = UiTransform.create(text)
    ui.width = 100
    ui.height = 100
    ui.widthUnit = YGUnit.YGU_PERCENT
    ui.heightUnit = YGUnit.YGU_PERCENT
    ui.pointerFilter = PointerFilterMode.PFM_NONE
    UiText.create(text, {
      value: this.takenMessage,
      font: Font.F_SANS_SERIF,
      fontSize: 40,
      textAlign: TextAlignMode.TAM_BOTTOM_CENTER
    })
    this.message = text
    this.messageTimer = MESSAGE_S
  }

  private hideMessage(): void {
    if (this.message !== null) engine.removeEntity(this.message)
    this.message = null
    this.messageTimer = 0
  }
}
